import React, { useEffect, useRef } from "react";
import { Terminal } from "xterm";
import { WebLinksAddon } from "xterm-addon-web-links";
import "xterm/css/xterm.css";
import "./styles.css"; // Import full-page terminal styling

const Portfolio = () => {
  const terminalRef = useRef(null);
  let commandBuffer = "";

  useEffect(() => {
    if (terminalRef.current) {
      const term = new Terminal({
        cursorBlink: true,
        allowTransparency: true,
        theme: {
          background: "#000",
          foreground: "#00FF00",
        },
      });

      const webLinksAddon = new WebLinksAddon();
      term.loadAddon(webLinksAddon);
      term.open(terminalRef.current);

      printWelcomeMessage(term);
      term.write("$ ");

      term.onData((data) => {
        if (data === "\r") { // Enter key
          term.writeln("");
          handleCommand(term, commandBuffer);
          commandBuffer = "";
          term.write("$ ");
        } else if (data === "\u007F") { // Backspace
          if (commandBuffer.length > 0) {
            commandBuffer = commandBuffer.slice(0, -1);
            term.write("\b \b");
          }
        } else {
          commandBuffer += data;
          term.write(data);
        }
      });

      // **Fix truncation & ensure responsive resizing**
      const resizeTerminal = () => {
        const cols = Math.floor((window.innerWidth - 20) / 9); // Fine-tuned to prevent truncation
        const rows = Math.floor((window.innerHeight - 20) / 18);
        term.resize(cols, rows);
      };

      window.addEventListener("resize", resizeTerminal);
      resizeTerminal();

      return () => window.removeEventListener("resize", resizeTerminal);
    }
  }, []);

  const printWelcomeMessage = (term) => {
    term.writeln("Welcome to Mohit Wadhwa's Portfolio!");
    term.writeln(" ");
    term.writeln("===============================================================================");
    term.writeln("Experience: 14+ years in IT");
    term.writeln("Specialization: ");
    term.writeln("- Mainframes & Legacy Modernization");
    term.writeln("- Over 10 years of experience in Maintenance & Support for Mainframe/Legacy Apps");
    term.writeln("- HealthCare, Merchant Finance & CreditCard Domains expertise");
    term.writeln("- DevOps & Automation Expert");
    term.writeln("- Certified with AWS's various certifications");
    term.writeln("===============================================================================");
    term.writeln(" ");
    term.writeln("Available Commands:");
    term.writeln("- 'projects' : View my projects");
    term.writeln("- 'skills'   : View my technical skills");
    term.writeln("- 'education': View my education");
    term.writeln("- 'contact'  : Get my contact information");
    term.writeln("- 'clear'    : To clear the screen");
    term.writeln(" ");
  };

  const handleCommand = (term, command) => {
    const cmd = command.trim().toLowerCase();
    switch (cmd) {
      case "projects":
        term.writeln("Projects:");
        term.writeln("- Mainframe to Cloud Migration");
        term.writeln("- COBOL Refactoring for Modern Systems");
        term.writeln("- API Integration for Legacy Systems using z/OS Connect");
        term.writeln(" ");
        break;
      case "skills":
        term.writeln("Technical Skills:");
        term.writeln("- COBOL, JCL, REXX, Python");
        term.writeln("- IBM Mainframe, z/OS, Db2, IMS");
        term.writeln("- Cloud Migration, API Development");
        term.writeln("- DevOps Tools: IDz, Gitlab, ADDI, UCDeploy, Artifactory");
        term.writeln(" ");
        break;
      case "education":
        term.writeln("Education:");
        term.writeln("- Bachelor's Degree in Electronics & Communication");
        term.writeln("- IBM Certified IDz, ADDI Developer");
        term.writeln(" ");
        break;
      case "contact":
        term.writeln("Contact:");
        term.writeln("- Email: mohit3wadhwa@gmail.com");
        term.writeln("- LinkedIn: https://www.linkedin.com/in/mohit-wadhwa-25a88a18/");
        term.writeln(" ");
        break;
      case "clear":
          window.location.reload(); // ✅ Refreshes the page
          break;
      default:
        term.writeln("Command not recognized. Try 'projects', 'skills', 'education', 'contact', or 'clear'.");
        term.writeln(" ");
    }
  };

  return (
    <div className="terminal-wrapper">
      <div className="terminal-container">
        <div ref={terminalRef} className="terminal"></div>
      </div>
    </div>
  );
};

export default Portfolio;
